import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'
import { refundPayment } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Farmer declines a pending order. This runs server-side (not in the
// dashboard) because issuing a real refund needs the Razorpay secret. Steps:
//   1. authorise the farmer and confirm the order is theirs and still pending
//   2. return the reserved stock
//   3. if the buyer paid by Razorpay, issue a real partial refund for this
//      line's amount and record it; other paid methods get a manual
//      'initiated' marker as before
//   4. mark the order declined
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getFarmerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const body = await req.json().catch(() => null)
  const reason = String((body as { reason?: unknown } | null)?.reason ?? '').trim().slice(0, 300)

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, farmer_id, status, quantity, total_price, produce_listing_id, payment_method, payment_status, razorpay_payment_id, order_code, shipped_at, collected_at, received_at')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.farmer_id !== session.farmerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  // A farmer can decline/cancel an order while it is still pending OR approved
  // but not yet fulfilled — the OrderCard offers Decline in both states (e.g.
  // the crop is damaged after the farmer already approved). Once it has been
  // shipped, picked up or received it's too late. Rejecting anything already
  // declined/cancelled also keeps a double-tap from refunding twice.
  if (order.status !== 'pending' && order.status !== 'approved') {
    return NextResponse.json({ error: 'This order can no longer be declined.' }, { status: 409 })
  }
  if (order.shipped_at || order.collected_at || order.received_at) {
    return NextResponse.json(
      { error: 'This order has already been fulfilled and can no longer be declined.' },
      { status: 409 },
    )
  }

  // 1. Return the reserved stock.
  if (order.produce_listing_id && order.quantity != null && order.quantity > 0) {
    try {
      await supabase.rpc('increment_stock', {
        p_listing_id: order.produce_listing_id,
        p_qty: order.quantity,
      })
    } catch (e) {
      console.error('[YFF] restock on decline failed:', e)
    }
  }

  // 2. Refund if the buyer actually paid.
  const update: Record<string, unknown> = { status: 'declined', decline_reason: reason || null }

  const paidByRazorpay = order.payment_status === 'paid' && !!order.razorpay_payment_id
  const paidByOther =
    order.payment_status === 'completed' ||
    order.payment_status === 'payment_claimed' ||
    order.payment_status === 'pending_confirmation'

  if (paidByRazorpay) {
    const amountPaise = Math.round((Number(order.total_price) || 0) * 100)
    if (amountPaise > 0) {
      try {
        const refund = await refundPayment({
          paymentId: order.razorpay_payment_id as string,
          amountPaise,
          notes: { order_code: order.order_code ?? '', order_id: order.id },
        })
        update.refund_id = refund.id
        update.refund_status = refund.status ?? 'processed'
        update.refund_amount = Math.round(refund.amountPaise / 100)
        update.refunded_at = new Date().toISOString()
      } catch (e) {
        // Refund failed at Razorpay. Don't silently swallow it — keep the
        // order pending so the farmer can retry, and surface the error.
        console.error('[YFF] razorpay refund failed:', e)
        return NextResponse.json(
          { error: 'Could not issue the refund. The order was not declined — please try again.' },
          { status: 502 },
        )
      }
    }
  } else if (paidByOther) {
    // Non-Razorpay paid (UPI/manual): flag for manual refund as before.
    update.refund_status = 'initiated'
  }

  const { error: updErr } = await supabase.from('orders').update(update).eq('id', id)
  if (updErr) {
    console.error('[YFF] decline update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not decline the order. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({
    ok: true,
    refunded: !!update.refund_id,
    refundStatus: (update.refund_status as string | undefined) ?? null,
  })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { refundPayment } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Buyer cancels their own order. Allowed any time UP TO the point the order is
// shipped or handed over — i.e. while still pending OR approved-and-awaiting.
// There is no time window; only the order's progress decides. Returns the stock
// and, for a paid order, issues a real Razorpay refund — same machinery as a
// farmer decline, but initiated by the buyer.
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  // Optional reason the buyer gave for cancelling.
  const body = await req.json().catch(() => null)
  const reason = String((body as { reason?: unknown } | null)?.reason ?? '').trim().slice(0, 300)

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, consumer_id, status, quantity, total_price, produce_listing_id, payment_status, razorpay_payment_id, created_at, order_code, shipped_at, collected_at, received_at, delivery_status')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  // Cancellable while still pending or approved-and-awaiting. Blocked once the
  // order is shipped (farmer shipped it, or a rider has picked it up and is in
  // transit) or resolved (picked up / delivered / received), and of course once
  // it's already declined / cancelled.
  const cancellable =
    (order.status === 'pending' || order.status === 'approved')
    && !order.shipped_at
    && !order.collected_at
    && !order.received_at
    && order.delivery_status !== 'picked_up'
    && order.delivery_status !== 'out_for_delivery'
    && order.delivery_status !== 'delivered'
  if (!cancellable) {
    return NextResponse.json(
      { error: 'This order can no longer be cancelled — it has already been shipped or completed.' },
      { status: 409 },
    )
  }

  // Return the reserved stock.
  if (order.produce_listing_id && order.quantity != null && order.quantity > 0) {
    try {
      await supabase.rpc('increment_stock', {
        p_listing_id: order.produce_listing_id,
        p_qty: order.quantity,
      })
    } catch (e) {
      console.error('[YFF] restock on cancel failed:', e)
    }
  }

  const update: Record<string, unknown> = {
    status: 'cancelled',
    decline_reason: reason || 'Cancelled by buyer',
  }

  const paidByRazorpay = order.payment_status === 'paid' && !!order.razorpay_payment_id
  const paidByOther =
    order.payment_status === 'completed' ||
    order.payment_status === 'payment_claimed' ||
    order.payment_status === 'pending_confirmation'

  if (paidByRazorpay) {
    const amountPaise = Math.round((Number(order.total_price) || 0) * 100)
    if (amountPaise > 0) {
      try {
        const refund = await refundPayment({
          paymentId: order.razorpay_payment_id as string,
          amountPaise,
          notes: { order_code: order.order_code ?? '', order_id: order.id, reason: 'buyer_cancel' },
        })
        update.refund_id = refund.id
        update.refund_status = refund.status ?? 'processed'
        update.refund_amount = Math.round(refund.amountPaise / 100)
        update.refunded_at = new Date().toISOString()
      } catch (e) {
        console.error('[YFF] razorpay refund on cancel failed:', e)
        return NextResponse.json(
          { error: 'Could not issue the refund. The order was not cancelled — please try again.' },
          { status: 502 },
        )
      }
    }
  } else if (paidByOther) {
    update.refund_status = 'initiated'
  }

  const { error: updErr } = await supabase.from('orders').update(update).eq('id', id)
  if (updErr) {
    console.error('[YFF] cancel update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not cancel the order. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({ ok: true, refunded: !!update.refund_id })
}

import { createHmac, timingSafeEqual } from 'crypto'
import Razorpay from 'razorpay'

// Server-only Razorpay helpers. The secret never leaves the server: it is
// used here to create orders and to verify the signature Checkout returns.
// The browser only ever sees the public key id (NEXT_PUBLIC_RAZORPAY_KEY_ID).

export function getRazorpayKeyId(): string {
  const id = process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID
  if (!id) throw new Error('NEXT_PUBLIC_RAZORPAY_KEY_ID is not set.')
  return id
}

function getRazorpaySecret(): string {
  const secret = process.env.RAZORPAY_KEY_SECRET
  if (!secret) throw new Error('RAZORPAY_KEY_SECRET is not set.')
  return secret
}

export function getRazorpayClient(): Razorpay {
  return new Razorpay({ key_id: getRazorpayKeyId(), key_secret: getRazorpaySecret() })
}

export type RefundResult = {
  id: string
  status: string | null
  amountPaise: number
}

// Issue a (partial) refund against a captured payment. Each cart line is a
// separate orders row sharing one payment id, so we refund only this line's
// amount — Razorpay supports partial refunds, and the sum across declined
// lines can never exceed the captured total. Throws on API failure so the
// caller can keep the order in a state that lets the farmer retry.
export async function refundPayment(args: {
  paymentId: string
  amountPaise: number
  notes?: Record<string, string>
}): Promise<RefundResult> {
  const refund = await getRazorpayClient().payments.refund(args.paymentId, {
    amount: args.amountPaise,
    speed: 'normal',
    notes: args.notes,
  })
  return {
    id: String(refund.id),
    status: (refund.status as string | undefined) ?? null,
    amountPaise: Number(refund.amount) || args.amountPaise,
  }
}

// Recompute the Checkout signature and compare in constant time. Razorpay
// signs `${order_id}|${payment_id}` with HMAC-SHA256 keyed by the secret.
// A matching signature is the only proof the browser callback is genuine —
// never trust a client-reported "success" without this.
export function verifyPaymentSignature(args: {
  razorpayOrderId: string
  razorpayPaymentId: string
  signature: string
}): boolean {
  const expected = createHmac('sha256', getRazorpaySecret())
    .update(`${args.razorpayOrderId}|${args.razorpayPaymentId}`)
    .digest('hex')
  const a = Buffer.from(expected)
  const b = Buffer.from(args.signature)
  if (a.length !== b.length) return false
  return timingSafeEqual(a, b)
}

// Verify a Razorpay WEBHOOK signature. Webhooks are signed with the webhook
// secret (configured in the dashboard, separate from the API key secret):
// HMAC-SHA256 over the raw request body, hex-encoded. We must verify against
// the EXACT bytes received, so the route reads req.text() before parsing.
export function verifyWebhookSignature(rawBody: string, signature: string | null | undefined): boolean {
  const secret = process.env.RAZORPAY_WEBHOOK_SECRET
  if (!secret) throw new Error('RAZORPAY_WEBHOOK_SECRET is not set.')
  if (!signature) return false
  const expected = createHmac('sha256', secret).update(rawBody).digest('hex')
  const a = Buffer.from(expected)
  const b = Buffer.from(signature)
  if (a.length !== b.length) return false
  return timingSafeEqual(a, b)
}

// Fetch all payment attempts Razorpay recorded against one order. Used by
// reconciliation to decide whether a "pending" order was actually paid.
export async function fetchOrderPayments(orderId: string): Promise<Array<{ id: string; status: string }>> {
  const res = await getRazorpayClient().orders.fetchPayments(orderId)
  const items = (res as { items?: Array<{ id: string; status: string }> }).items ?? []
  return items.map((p) => ({ id: String(p.id), status: String(p.status) }))
}

// The shape we care about from a Razorpay payment entity (available both from
// payments.fetch and inside the payment.captured webhook payload).
export type RazorpayPaymentEntity = {
  method?: string | null
  vpa?: string | null
  wallet?: string | null
  bank?: string | null
  card?: { network?: string | null } | null
}

// Map a UPI VPA handle (the part after "@") to the app the buyer paid with.
// The handle is the most reliable signal Razorpay gives us — there is no
// explicit "app name" field for UPI.
function upiAppFromVpa(vpa?: string | null): string | null {
  if (!vpa || !vpa.includes('@')) return null
  const handle = vpa.split('@')[1]?.toLowerCase() ?? ''
  // PhonePe issues @ybl / @ibl / @axl (and @yapl for some banks).
  if (['ybl', 'ibl', 'axl', 'yapl'].includes(handle)) return 'PhonePe'
  // Google Pay handles all start with "ok" (okaxis, oksbi, okhdfcbank, okicici).
  if (handle.startsWith('ok')) return 'Google Pay'
  // Paytm.
  if (['paytm', 'ptyes', 'ptaxis', 'pthdfc', 'ptsbi'].includes(handle)) return 'Paytm'
  // Amazon Pay.
  if (handle === 'apl' || handle === 'amazonpay') return 'Amazon Pay'
  // CRED.
  if (handle === 'axisb' && (vpa.startsWith('cred') || vpa.includes('.cred'))) return 'CRED'
  return null
}

// Turn a Razorpay payment entity into a friendly label we can show buyers,
// e.g. "PhonePe", "Google Pay", "Paytm", "UPI", "Visa card", "HDFC NetBanking".
// Returns null when nothing useful can be derived.
export function resolvePaymentLabel(p: RazorpayPaymentEntity | null | undefined): string | null {
  if (!p) return null
  const method = (p.method ?? '').toLowerCase()
  if (method === 'upi') return upiAppFromVpa(p.vpa) ?? 'UPI'
  if (method === 'wallet') {
    const w = (p.wallet ?? '').toLowerCase()
    const map: Record<string, string> = {
      phonepe: 'PhonePe', paytm: 'Paytm', amazonpay: 'Amazon Pay',
      freecharge: 'Freecharge', mobikwik: 'MobiKwik', airtelmoney: 'Airtel Money',
    }
    return map[w] ?? (p.wallet ? `${p.wallet} wallet` : 'Wallet')
  }
  if (method === 'card') {
    const net = p.card?.network
    return net ? `${net} card` : 'Card'
  }
  if (method === 'netbanking') return p.bank ? `${p.bank} NetBanking` : 'NetBanking'
  if (method === 'emi') return 'EMI'
  if (method) return method.toUpperCase()
  return null
}

// Fetch a single payment from Razorpay and resolve its friendly method label.
// Used by the verify route; failures are swallowed (label stays null) so a
// transient API hiccup never blocks marking the order paid.
export async function fetchPaymentMethodLabel(paymentId: string): Promise<string | null> {
  try {
    const p = (await getRazorpayClient().payments.fetch(paymentId)) as RazorpayPaymentEntity
    return resolvePaymentLabel(p)
  } catch (e) {
    console.error('[YFF] fetchPaymentMethodLabel failed:', e)
    return null
  }
}

import { createClient } from '@supabase/supabase-js'
import { randomInt } from 'crypto'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { createGuestOrderToken } from '@/lib/guest-order-token'
import { getTierPrice } from '@/lib/pricing'
import { normalizePhone } from '@/lib/phone'
import { DELIVERY_FEE_RUPEES } from '@/lib/delivery-fee'
import { getPlatformFeePercent, computePlatformFee } from '@/lib/platform-fee'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

type IncomingItem = { listingId: string; qty: number }

// Pragmatic email check — we only need to reject obvious junk, not enforce
// RFC 5322. The real signal is whether the buyer can be reached.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

// 4-digit handover code, generated server-side at order placement. The
// customer reads it off their order page to whoever hands over the goods —
// the rider (home delivery) or the farmer (self-pickup) — who confirms it in
// their dashboard. crypto.randomInt avoids Math.random's predictability.
function generateHandoverOtp(): string {
  return String(randomInt(0, 10000)).padStart(4, '0')
}

type ListingRow = {
  id: string
  name: string
  unit: string | null
  stock_qty: number | null
  status: string | null
  farmer_id: string
  price_tier_1_qty: number | null
  price_tier_1_price: number | null
  price_tier_2_qty: number | null
  price_tier_2_price: number | null
  price_tier_3_price: number | null
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function bad(msg: string, status = 400) {
  return NextResponse.json({ error: msg }, { status })
}

export async function POST(req: NextRequest) {
  // No session is fine — guests may check out by providing name, email,
  // mobile, and address below (see the `guest` branch).
  const session = getConsumerSessionFromRequest(req)

  const body = await req.json().catch(() => null) as
    | {
        farmerId?: string
        paymentMethod?: string
        pickupLocation?: string | null
        items?: IncomingItem[]
        deliveryType?: string
        deliveryAddress?: string | null
        deliveryCity?: string | null
        deliveryLandmark?: string | null
        deliveryPincode?: string | null
        deliveryAltPhone?: string | null
        idempotencyKey?: string | null
        guest?: { name?: string; email?: string; phone?: string } | null
      }
    | null

  if (!body) return bad('Invalid request body.')
  const { farmerId, paymentMethod, pickupLocation, items } = body
  // Optional idempotency key (a client-generated UUID per checkout attempt).
  const idempotencyKey = typeof body.idempotencyKey === 'string' && UUID_RE.test(body.idempotencyKey)
    ? body.idempotencyKey
    : null

  if (!farmerId || !UUID_RE.test(farmerId)) return bad('Invalid farmer.')
  if (paymentMethod !== 'upi' && paymentMethod !== 'cod' && paymentMethod !== 'razorpay') {
    return bad('Invalid payment method.')
  }
  if (!Array.isArray(items) || items.length === 0) return bad('Cart is empty.')
  if (items.length > 50) return bad('Too many items.')
  for (const it of items) {
    if (!it || typeof it !== 'object') return bad('Invalid item.')
    if (!it.listingId || !UUID_RE.test(it.listingId)) return bad('Invalid listing id.')
    if (!Number.isFinite(it.qty) || it.qty <= 0 || it.qty > 10000) return bad('Invalid quantity.')
  }

  // Guest checkout: no session, so the buyer's identity comes from the request.
  // We still never trust the client for prices or stock — only for who they are.
  const isGuest = !session
  let guestName: string | null = null
  let guestEmail: string | null = null
  let guestPhone: string | null = null
  if (isGuest) {
    guestName = String(body.guest?.name ?? '').trim().slice(0, 80)
    guestEmail = String(body.guest?.email ?? '').trim().toLowerCase().slice(0, 200)
    guestPhone = normalizePhone(body.guest?.phone)
    if (!guestName) return bad('Please enter your name.')
    if (!EMAIL_RE.test(guestEmail)) return bad('Enter a valid email address.')
    if (!guestPhone) return bad('Enter a valid 10-digit mobile number.')
  }

  // self_pickup → buyer collects from the farm; home_delivery → our rider
  // brings it; courier → the farmer ships it themselves. Both delivery kinds
  // need a destination address.
  const deliveryType =
    body.deliveryType === 'home_delivery' ? 'home_delivery'
    : body.deliveryType === 'courier' ? 'courier'
    : 'self_pickup'
  const needsAddress = deliveryType === 'home_delivery' || deliveryType === 'courier'
  let deliveryAddress: string | null = null
  let deliveryCity: string | null = null
  let deliveryLandmark: string | null = null
  let deliveryPincode: string | null = null
  let deliveryAltPhone: string | null = null

  if (needsAddress) {
    deliveryAddress = String(body.deliveryAddress ?? '').trim().slice(0, 400)
    deliveryCity = String(body.deliveryCity ?? '').trim().slice(0, 100) || null
    deliveryLandmark = String(body.deliveryLandmark ?? '').trim().slice(0, 200) || null
    const rawPincode = String(body.deliveryPincode ?? '').trim()
    deliveryPincode = /^\d{6}$/.test(rawPincode) ? rawPincode : null
    const altPhone = normalizePhone(body.deliveryAltPhone)
    deliveryAltPhone = altPhone || null

    if (!deliveryAddress) return bad('Enter your delivery address.')
    if (deliveryAddress.length < 10) return bad('Delivery address looks too short. Please add door no, street, and area.')
    if (!deliveryCity) return bad('Enter your city or town.')
    if (!deliveryPincode) return bad('Enter a valid 6-digit pincode.')
  } else if (isGuest) {
    // Guests must always give an address, even for self-pickup, so the farmer
    // has a contact/record on file. We store it in delivery_address.
    deliveryAddress = String(body.deliveryAddress ?? '').trim().slice(0, 400)
    if (!deliveryAddress) return bad('Enter your address.')
    if (deliveryAddress.length < 10) return bad('Address looks too short. Please add door no, street, and area.')
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Resolve the authoritative buyer. For accounts we read name/phone from the
  // DB (never the client); for guests we use the values validated above and
  // leave consumer_id NULL.
  let buyerId: string | null = null
  let buyerName: string
  let buyerPhone: string
  let buyerEmail: string | null = null
  if (session) {
    const { data: consumer } = await supabase
      .from('consumers_auth')
      .select('id, name, phone')
      .eq('id', session.consumerId)
      .maybeSingle()
    if (!consumer) return bad('Account not found. Please log in again.', 401)
    buyerId = consumer.id
    buyerName = consumer.name || 'Buyer'
    buyerPhone = consumer.phone
  } else {
    buyerName = guestName || 'Buyer'
    buyerPhone = guestPhone!
    buyerEmail = guestEmail
  }

  // Idempotency: if this checkout attempt was already saved (double-tap or a
  // retry after a lost response), return the existing rows instead of placing
  // a second order and decrementing stock again. Guest orders have no
  // consumer_id, so we match on the (random UUID) key alone for them.
  if (idempotencyKey) {
    let existingQuery = supabase
      .from('orders')
      .select('id, order_code, total_price, delivery_fee')
      .eq('idempotency_key', idempotencyKey)
    existingQuery = buyerId
      ? existingQuery.eq('consumer_id', buyerId)
      : existingQuery.is('consumer_id', null)
    const { data: existing } = await existingQuery
    if (existing && existing.length > 0) {
      const existingTotal = existing.reduce((s, o) => s + (Number(o.total_price) || 0), 0)
      const existingFee = existing.reduce((s, o) => s + (Number(o.delivery_fee) || 0), 0)
      const existingIds = existing.map((r) => r.id)
      return NextResponse.json({
        ok: true,
        orderIds: existingIds,
        orderCodes: existing.map((r) => (r as { order_code?: string | null }).order_code).filter(Boolean),
        total: existingTotal,
        deliveryFee: existingFee,
        grandTotal: existingTotal + existingFee,
        deduplicated: true,
        ...(isGuest ? { guestToken: createGuestOrderToken(existingIds) } : {}),
      })
    }
  }

  // Farmer COD acceptance check
  const { data: farmer } = await supabase
    .from('farmers')
    .select('id, cod_enabled')
    .eq('id', farmerId)
    .maybeSingle()

  if (!farmer) return bad('Farmer not found.', 404)
  if (paymentMethod === 'cod' && farmer.cod_enabled !== true) {
    return bad('This farmer is not accepting Cash on Delivery.')
  }

  // Pull live listing rows — never trust prices from the client cart
  const listingIds = items.map((i) => i.listingId)
  const { data: listings } = await supabase
    .from('produce_listings')
    .select(
      'id, name, unit, stock_qty, status, farmer_id, price_tier_1_qty, price_tier_1_price, price_tier_2_qty, price_tier_2_price, price_tier_3_price',
    )
    .in('id', listingIds) as { data: ListingRow[] | null }

  if (!listings || listings.length !== listingIds.length) {
    return bad('One or more items in your cart are no longer available.')
  }

  const listingById = new Map(listings.map((l) => [l.id, l]))
  const rows: Array<Record<string, unknown>> = []
  let total = 0
  // One OTP for the whole batch. Home delivery: the rider does a single
  // handover at the door. Self-pickup: the customer reads it to the farmer at
  // collection. Either way the whole checkout shares one code.
  const sharedHandoverOtp = generateHandoverOtp()
  const deliveryFee = deliveryType === 'home_delivery' ? DELIVERY_FEE_RUPEES : 0

  // Validate first (price + ownership) before we touch any stock. Stock
  // claims happen below with the RPC so two cart submits can't oversell.
  for (const item of items) {
    const listing = listingById.get(item.listingId)
    if (!listing) return bad('Item missing.')
    if (listing.farmer_id !== farmerId) return bad('Items must belong to the same farmer.')
    // Block ordering a listing the farmer (or moderator) has taken down. A
    // stale cart could still hold a since-paused/suspended item; only
    // 'available' produce may be purchased.
    if (listing.status !== 'available') {
      return bad(`${listing.name} is no longer available.`)
    }

    const unitPrice = getTierPrice(item.qty, {
      priceTier1Qty: listing.price_tier_1_qty,
      priceTier1Price: listing.price_tier_1_price,
      priceTier2Qty: listing.price_tier_2_qty,
      priceTier2Price: listing.price_tier_2_price,
      priceTier3Price: listing.price_tier_3_price,
    })

    const linePrice = unitPrice != null ? Math.round(unitPrice * item.qty) : null
    if (linePrice == null || linePrice <= 0) {
      return bad(`Price not set for ${listing.name}. Please ask the farmer.`)
    }
    total += linePrice

    rows.push({
      farmer_id: farmerId,
      produce_listing_id: listing.id,
      produce_name: listing.name,
      quantity: item.qty,
      unit: listing.unit || 'kg',
      total_price: linePrice,
      buyer_name: buyerName,
      buyer_phone: buyerPhone,
      buyer_email: buyerEmail,
      consumer_id: buyerId,
      idempotency_key: idempotencyKey,
      pickup_location: typeof pickupLocation === 'string' ? pickupLocation.slice(0, 200) : null,
      status: 'pending',
      payment_method: paymentMethod,
      payment_status: 'pending',
      delivery_type: deliveryType,
      delivery_status: deliveryType === 'home_delivery' ? 'unassigned' : null,
      delivery_address: deliveryAddress,
      delivery_city: deliveryCity,
      delivery_landmark: deliveryLandmark,
      delivery_pincode: deliveryPincode,
      delivery_alt_phone: deliveryAltPhone,
      handover_otp: sharedHandoverOtp,
      // Fee is paid once per cart, so we stamp it on the first row only.
      // sum(delivery_fee) and sum(rider_payout) over a batch === one fee.
      delivery_fee: 0,
      rider_payout: 0,
    })
  }

  if (rows.length > 0 && deliveryFee > 0) {
    rows[0].delivery_fee = deliveryFee
    rows[0].rider_payout = deliveryFee
  }

  // Platform fee (moderator commission) — a % of the cart subtotal, added on top
  // and stamped once per batch (first row), mirroring delivery_fee. Resolved
  // server-side; 0 unless the moderator has set a fee. Only written when > 0, so
  // the column is never referenced before its migration runs.
  const feePercent = await getPlatformFeePercent(supabase)
  const platformFee = computePlatformFee(total, feePercent)
  if (rows.length > 0 && platformFee > 0) {
    rows[0].platform_fee = platformFee
  }

  // Atomic stock claim. decrement_stock returns false if the listing went
  // below zero (or vanished). On any failure we revert prior claims so we
  // don't leak inventory.
  const claimed: Array<{ listingId: string; qty: number }> = []
  const revertClaims = async () => {
    for (const c of claimed) {
      try {
        await supabase.rpc('increment_stock', { p_listing_id: c.listingId, p_qty: c.qty })
      } catch (e) {
        console.error('[YFF] increment_stock revert failed:', e)
      }
    }
  }
